@media (forced-colors: active) {
  /* The map keeps its author colours where they carry meaning (a pin is an
     annotation on top of the tiles, which the mode leaves alone too). */
  .map-marker {
    border: 2px solid ButtonBorder;
    background: ButtonFace;
    color: ButtonText;
  }

  .map-marker.map-cluster {
    border-width: 3px;
  }

  /* Selected / previewed / hovered pins: an outline is what survives, because
     the mode drops the background colour that used to say “selected”. */
  .map-marker.is-selected,
  .map-marker[aria-current='true'] {
    background: Highlight;
    color: HighlightText;
    outline: 3px solid Highlight;
    outline-offset: 1px;
  }

  .map-marker.is-preview {
    outline: 3px dashed Highlight;
    outline-offset: 2px;
  }

  /* Extents and the point crosshair are outline-only drawings in this mode: the
     translucent fills are dropped, the dashed/solid outline is the information. */
  .map-extent {
    border: 3px dashed CanvasText;
    background: none;
  }

  .map-point {
    border: 3px solid CanvasText;
    background: none;
  }

  .map-footprint {
    border: 2px solid CanvasText;
  }

  .map-footprint.is-preview,
  .map-footprint.is-selected {
    border: 3px dashed CanvasText;
    background: none;
  }

  /* The selected or previewed row: the mode drops `background` and the
     accent-coloured left rule, so both states get a border of their own. */
  .zh-result[aria-current='true'],
  .zh-result.is-revealed {
    border: 3px double Highlight;
    border-left: 8px solid Highlight;
    outline: 1px solid Highlight;
    outline-offset: 1px;
  }

  .zh-result.is-preview {
    border: 3px dashed Highlight;
  }

  /* Histogram: bars are drawn with `background` only, which the mode would turn
     into the canvas colour — invisible. System colours keep the chart readable,
     and the selected/brushed decades keep their Highlight fill. */
  .zh-histogram__bar {
    background: ButtonText;
    opacity: 1;
  }

  .zh-histogram__bin[aria-current='true'] .zh-histogram__bar,
  .zh-histogram__bin.is-brushing .zh-histogram__bar {
    background: Highlight;
  }

  /* An empty decade keeps its faint bar: a system GrayText can render as the
     canvas colour in some palettes, so the faintness comes from `opacity`
     (which the mode does not replace) on the same readable ButtonText. */
  .zh-histogram__bin.is-empty .zh-histogram__bar {
    background: ButtonText;
    opacity: 0.4;
  }

  .zh-histogram__bin.is-brushing {
    outline: 1px solid Highlight;
  }
}

