/** Tiny CDP helper reused by the shell probes (no npm deps). */
import { spawn } from 'node:child_process';
import { existsSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const CHROME = ['chromium', 'chromium-browser', 'google-chrome', 'google-chrome-stable'].find((bin) => {
  for (const dir of (process.env.PATH || '').split(':')) if (dir && existsSync(path.join(dir, bin))) return true;
  return false;
});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function launch({ port = 9333, width = 1440, height = 960 } = {}) {
  const userDataDir = path.join(os.tmpdir(), `kz-probe-${process.pid}-${port}`);
  const chrome = spawn(
    CHROME,
    [
      '--headless=new',
      '--no-sandbox',
      '--disable-gpu',
      '--disable-dev-shm-usage',
      '--hide-scrollbars',
      `--window-size=${width},${height}`,
      `--remote-debugging-port=${port}`,
      `--user-data-dir=${userDataDir}`,
      'about:blank',
    ],
    { stdio: ['ignore', 'pipe', 'pipe'] },
  );
  const deadline = Date.now() + 30_000;
  let target = null;
  while (Date.now() < deadline) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' });
      if (res.ok) {
        const info = await res.json();
        if (info.webSocketDebuggerUrl) {
          target = info.webSocketDebuggerUrl;
          break;
        }
      }
    } catch {}
    await sleep(300);
  }
  if (!target) throw new Error('no devtools target');
  const ws = new WebSocket(target);
  await new Promise((res, rej) => {
    ws.addEventListener('open', res, { once: true });
    ws.addEventListener('error', rej, { once: true });
  });
  let id = 0;
  const pending = new Map();
  const events = [];
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    } else if (msg.method) events.push(msg);
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const mid = ++id;
      pending.set(mid, { resolve, reject });
      ws.send(JSON.stringify({ id: mid, method, params }));
    });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Network.enable');
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: width < 700 });

  const cdp = {
    send,
    events,
    async goto(url) {
      const loaded = new Promise((res) => {
        const t = setInterval(() => {
          if (events.some((e) => e.method === 'Page.loadEventFired')) {
            clearInterval(t);
            res();
          }
        }, 50);
        setTimeout(() => {
          clearInterval(t);
          res();
        }, 30_000);
      });
      await send('Page.navigate', { url });
      await loaded;
    },
    async eval(expression) {
      const r = await send('Runtime.evaluate', {
        expression,
        awaitPromise: true,
        returnByValue: true,
        userGesture: true,
      });
      if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'eval failed');
      return r.result.value;
    },
    async shot(file, clip) {
      const params = { format: 'png' };
      if (clip) params.clip = { ...clip, scale: 1 };
      const r = await send('Page.captureScreenshot', params);
      const { writeFile } = await import('node:fs/promises');
      await writeFile(file, Buffer.from(r.data, 'base64'));
      return file;
    },
    async setViewport(width, height, mobile = width < 700) {
      await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile });
    },
    async key(key, code, keyCode, extra = {}) {
      await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code, windowsVirtualKeyCode: keyCode, ...extra });
      await send('Input.dispatchKeyEvent', { type: 'keyUp', key, code, windowsVirtualKeyCode: keyCode, ...extra });
    },
    async close() {
      try {
        ws.close();
      } catch {}
      chrome.kill('SIGKILL');
    },
  };
  return cdp;
}

import { launch } from '/tmp/probe/cdp.mjs';

const URL_BASE = process.env.BASE || 'http://127.0.0.1:8787';
const cdp = await launch({ width: 1440, height: 960 });

async function metrics(width, height) {
  await cdp.setViewport(width, height);
  await cdp.goto(`${URL_BASE}/`);
  await new Promise((r) => setTimeout(r, 3500));
  const m = await cdp.eval(`(() => {
    const rect = (sel) => { const el = document.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top + window.scrollY), h: Math.round(r.height) }; };
    const first = (sel) => { const el = document.querySelector(sel); return el ? { top: Math.round(el.getBoundingClientRect().top + window.scrollY), h: Math.round(el.getBoundingClientRect().height) } : null; };
    return {
      viewport: [innerWidth, innerHeight],
      header: first('.zh-header'),
      intro: first('.app-intro'),
      toolbar: first('.app-toolbar') || first('.app-controls'),
      map: first('#map') || first('.app-map'),
      search: first('#place-search') || first('form[role="search"]'),
      overflowX: document.documentElement.scrollWidth - innerWidth,
      bodyText: document.body.innerText.slice(0, 0),
      toolbarChildren: [...(document.querySelector('.app-toolbar') || document.querySelector('.app-controls') || document.createElement('div')).children].map((c) => ({ cls: c.className, h: Math.round(c.getBoundingClientRect().height), txt: (c.textContent || '').trim().slice(0, 40) })),
    };
  })()`);
  console.log(`\n=== ${width}x${height} ===`);
  console.log(JSON.stringify(m, null, 1));
}

await metrics(1440, 960);
await metrics(390, 844);
await metrics(360, 740);
await metrics(320, 640);
await cdp.close();

