cd /tmp && cat > /tmp/probe/tilecolor.mjs <<'EOF'
import { launch } from '/tmp/probe/cdp.mjs';
const cdp = await launch({ width: 300, height: 200, port: 9345 });
const urls = process.argv.slice(2);
await cdp.goto('about:blank');
const out = await cdp.eval(`(async () => {
  const urls = ${JSON.stringify(urls)};
  const res = [];
  for (const u of urls) {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    await new Promise((r) => { img.onload = r; img.onerror = r; img.src = u; });
    if (!img.naturalWidth) { res.push({ u, error: true }); continue; }
    const c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const g = c.getContext('2d');
    g.drawImage(img, 0, 0);
    const d = g.getImageData(0, 0, c.width, c.height).data;
    const hist = new Map();
    for (let i = 0; i < d.length; i += 4 * 37) {
      const k = [d[i], d[i+1], d[i+2]].join(',');
      hist.set(k, (hist.get(k) || 0) + 1);
    }
    const top = [...hist.entries()].sort((a,b)=>b[1]-a[1]).slice(0,4);
    res.push({ u, size: [c.width, c.height], topColors: top });
  }
  return res;
})()`);
console.log(JSON.stringify(out, null, 1));
await cdp.close();
