#!/usr/bin/env node
/**
 * Build `public/data/world.geo.json` — the world outline of the “Welt” base map.
 *
 * Why a build step and not a runtime fetch of a third-party tile service:
 * the map's raster base layers come from swisstopo and only cover Switzerland.
 * Outside the country the service answers either a white tile or a 404, so the
 * seed's 60-odd world, Europe and overseas sheets had a blank background. The
 * outline is therefore shipped with the site (no tile server, no API key, works
 * offline like the rest of the map) and drawn by `public/app/world.js`.
 *
 * Data: **Natural Earth 1:110m Admin-0 countries** — public domain, no
 * attribution required (we credit it anyway). The file is *derived* data: the
 * script keeps the country names, the ISO code and the rings, rounds the
 * coordinates to three decimals (~110 m) and writes one compact JSON file. It
 * never invents geometry.
 *
 * Usage:
 *   node scripts/build-world.mjs                        # download + build
 *   node scripts/build-world.mjs --in /tmp/ne.geojson   # build from a local file
 *   node scripts/build-world.mjs --check                # verify the shipped file
 *
 * `--check` is part of `npm run check`: it re-reads the shipped file and fails
 * if the metadata, the country count or the coordinate range is implausible, so
 * a hand-edited file cannot quietly become fake geography.
 */
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

const DEFAULT_SOURCE = {
  url: 'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_admin_0_countries.geojson',
  dataset: 'ne_110m_admin_0_countries',
  page: 'https://www.naturalearthdata.com/downloads/110m-cultural-vectors/110m-admin-0-countries/',
  repository: 'https://github.com/nvkelso/natural-earth-vector',
  license: 'Public domain (Natural Earth); credit appreciated, not required',
};

/** Coordinates are rounded to ~110 m — below the world map's smallest pixel. */
const DECIMALS = 3;
/** A ring needs an area to be worth drawing as land, not as a speck. */
const MIN_RING_AREA = 0.0005; // square degrees (~6 km² at the equator)

const args = process.argv.slice(2);
const argValue = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = path.resolve(root, argValue('out', 'public/data/world.geo.json'));

const round = (value) => Number(value.toFixed(DECIMALS));

/** Shoelace area in square degrees; the sign is irrelevant here. */
export function ringArea(ring) {
  let sum = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[i + 1];
    sum += x1 * y2 - x2 * y1;
  }
  return Math.abs(sum / 2);
}

/** Drop duplicate neighbours (the source repeats points on shared borders). */
export function dedupe(ring) {
  const out = [];
  for (const point of ring) {
    const last = out[out.length - 1];
    if (last && last[0] === point[0] && last[1] === point[1]) continue;
    out.push(point);
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    // A closed ring that lost its last point to rounding is still a ring.
    if (first[0] === last[0] && first[1] === last[1]) out.pop();
  }
  return out;
}

/** GeoJSON (Polygon | MultiPolygon) -> [ring, …] in rounded degrees. */
export function ringsOf(geometry) {
  if (!geometry) return [];
  const polygons = geometry.type === 'Polygon' ? [geometry.coordinates] : geometry.type === 'MultiPolygon' ? geometry.coordinates : [];
  const rings = [];
  for (const polygon of polygons) {
    // The first ring of a polygon is its outline; holes (lakes, enclaves) are
    // drawn as part of the land mass, which is what a 110m outline needs.
    const outer = polygon[0];
    if (!Array.isArray(outer)) continue;
    const ring = dedupe(outer.map(([lon, lat]) => [round(lon), round(lat)]));
    if (ring.length < 4) continue;
    if (ringArea([...ring, ring[0]]) < MIN_RING_AREA) continue;
    rings.push(ring);
  }
  return rings;
}

export function buildOutline(geojson, { retrieved = new Date().toISOString().slice(0, 10), source = DEFAULT_SOURCE } = {}) {
  const countries = [];
  for (const feature of geojson.features ?? []) {
    const props = feature.properties ?? {};
    const name = props.NAME ?? props.ADMIN ?? props.name;
    if (!name) continue;
    const rings = ringsOf(feature.geometry);
    if (rings.length === 0) continue;
    countries.push({
      name,
      nameDe: props.NAME_DE ?? null,
      iso: props.ISO_A3 && props.ISO_A3 !== '-99' ? props.ISO_A3 : null,
      rings,
    });
  }
  countries.sort((a, b) => a.name.localeCompare(b.name, 'en'));
  let points = 0;
  let west = 180;
  let east = -180;
  let south = 90;
  let north = -90;
  for (const country of countries) {
    for (const ring of country.rings) {
      points += ring.length;
      for (const [lon, lat] of ring) {
        if (lon < west) west = lon;
        if (lon > east) east = lon;
        if (lat < south) south = lat;
        if (lat > north) north = lat;
      }
    }
  }
  return {
    meta: {
      dataset: source.dataset,
      title: 'Natural Earth 1:110m Admin-0 countries (world outline)',
      source: source.url,
      sourcePage: source.page,
      repository: source.repository,
      license: source.license,
      retrieved,
      generator: 'scripts/build-world.mjs',
      decimals: DECIMALS,
      countries: countries.length,
      points,
    },
    bbox: { west, east, south, north },
    countries,
  };
}

/** Sanity rules for the shipped file; `--check` and the tests use them. */
export function checkOutline(outline) {
  const problems = [];
  const meta = outline?.meta ?? {};
  if (!Array.isArray(outline?.countries) || outline.countries.length < 150) {
    problems.push(`countries: ${outline?.countries?.length ?? 'none'} (expected ≥ 150)`);
  }
  if (!/naturalearth/i.test(String(meta.source ?? ''))) problems.push('meta.source does not name Natural Earth');
  if (!/public domain/i.test(String(meta.license ?? ''))) problems.push('meta.license is not the public-domain statement');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(meta.retrieved ?? ''))) problems.push('meta.retrieved is not a date');
  if (!meta.points || meta.points < 3000) problems.push(`meta.points: ${meta.points ?? 'none'}`);
  const bbox = outline?.bbox ?? {};
  if (!(bbox.west >= -180 && bbox.east <= 180 && bbox.west < bbox.east)) problems.push('bbox is not a real longitude range');
  if (!(bbox.south >= -90 && bbox.north <= 90 && bbox.south < bbox.north)) problems.push('bbox is not a real latitude range');
  const names = new Set();
  for (const country of outline?.countries ?? []) {
    if (!country.name) problems.push('a country without a name');
    if (names.has(country.name)) problems.push(`duplicate country: ${country.name}`);
    names.add(country.name);
    if (!Array.isArray(country.rings) || country.rings.length === 0) problems.push(`${country.name}: no rings`);
    for (const ring of country.rings ?? []) {
      if (!Array.isArray(ring) || ring.length < 4) problems.push(`${country.name}: ring with ${ring?.length ?? 0} points`);
      for (const point of ring ?? []) {
        if (!Array.isArray(point) || point.length !== 2) {
          problems.push(`${country.name}: malformed point`);
          break;
        }
        const [lon, lat] = point;
        if (!(lon >= -180 && lon <= 180 && lat >= -90 && lat <= 90)) problems.push(`${country.name}: point outside the world (${lon}, ${lat})`);
      }
    }
  }
  for (const required of ['Switzerland', 'Germany', 'Japan', 'Brazil']) {
    if (!names.has(required)) problems.push(`missing country: ${required}`);
  }
  return problems;
}

async function source(args) {
  const local = argValue('in', '');
  if (local) return JSON.parse(await readFile(path.resolve(local), 'utf8'));
  const url = argValue('source', DEFAULT_SOURCE.url);
  const res = await fetch(url, { headers: { 'user-agent': 'Kartenzeit build (world outline)', accept: 'application/geo+json, application/json' } });
  if (!res.ok) throw new Error(`${url} answered ${res.status}`);
  return res.json();
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))) {
  if (args.includes('--check')) {
    const outline = JSON.parse(await readFile(OUT, 'utf8'));
    const problems = checkOutline(outline);
    if (problems.length > 0) {
      console.error(`✖ ${path.relative(root, OUT)} failed its checks:`);
      for (const problem of problems) console.error(`  - ${problem}`);
      process.exit(1);
    }
    console.log(`✔ ${path.relative(root, OUT)}: ${outline.meta.countries} countries, ${outline.meta.points} points, ${outline.meta.retrieved}, ${outline.meta.license}`);
  } else {
    const geojson = await source(args);
    const outline = buildOutline(geojson, { source: { ...DEFAULT_SOURCE, url: argValue('source', DEFAULT_SOURCE.url) } });
    const problems = checkOutline(outline);
    if (problems.length > 0) {
      console.error('✖ the built outline failed its own checks:');
      for (const problem of problems) console.error(`  - ${problem}`);
      process.exit(1);
    }
    await writeFile(OUT, `${JSON.stringify(outline)}\n`);
    const bytes = (await readFile(OUT)).byteLength;
    console.log(
      `✔ ${path.relative(root, OUT)}: ${outline.meta.countries} countries, ${outline.meta.points} points, ${(bytes / 1024).toFixed(0)} KiB ` +
        `(bbox ${outline.bbox.west}…${outline.bbox.east} / ${outline.bbox.south}…${outline.bbox.north})`,
    );
  }
}

