/**
 * “Welt” base map — the global outline under the app's raster base layers.
 *
 * Why this module exists: the two documented raster base layers come from
 * swisstopo and cover **Switzerland only**. Outside the country the WMTS
 * answers a white tile (verified 2026-10-19: `ch.swisstopo.pixelkarte-farbe`
 * returns an all-white 256×256 JPEG for a tile over the North Sea) or a 404 for
 * tiles further away, so a whole-globe record or an overseas sheet sat on a
 * blank surface. The seed carries 60+ such records.
 *
 * The outline is **shipped with the site** (`/data/world.geo.json`, built by
 * `scripts/build-world.mjs` from Natural Earth 1:110m Admin-0 countries, public
 * domain). No tile server, no key, no third party in the request path, and the
 * layer keeps working offline like the rest of the map.
 *
 * The module is deliberately split into pure functions (`normaliseOutline`,
 * `planWorldPaths`) and one painter, so the geometry can be unit-tested in Node
 * without a canvas.
 */

export const WORLD_OUTLINE_URL = '/data/world.geo.json';
/** The map's tile size in CSS pixels; the projection must match `map.js`. */
export const TILE = 256;
/** Latitude range of the Web Mercator projection (same clamp as `map.js`). */
export const MERCATOR_MAX_LAT = 85.05112878;
/** How far outside the viewport a point may fall before it is clamped. */
const CLAMP_MARGIN = 2;
/** A country whose bbox is smaller than this is still drawn: it may be a view. */
const MIN_RING_POINTS = 4;

/**
 * Longitude/latitude to world pixels at a zoom level. Mirrors
 * `lonToTileX`/`latToTileY` in `public/app/map.js`; `tests/world.test.mjs`
 * asserts both agree, so the two cannot drift apart silently.
 */
export function projectLon(lon, z) {
  return ((lon + 180) / 360) * 2 ** z * TILE;
}
export function projectLat(lat, z) {
  const clamped = Math.max(-MERCATOR_MAX_LAT, Math.min(MERCATOR_MAX_LAT, lat));
  const s = Math.sin((clamped * Math.PI) / 180);
  return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * 2 ** z * TILE;
}
/** Inverse, used to turn the viewport into a longitude/latitude window. */
export function unprojectLon(x, z) {
  return (x / (2 ** z * TILE)) * 360 - 180;
}
export function unprojectLat(y, z) {
  const n = Math.PI - (2 * Math.PI * (y / (2 ** z * TILE)));
  return (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
}

/** Bounding box of one ring, in degrees. */
export function ringBounds(ring) {
  let west = 180;
  let east = -180;
  let south = 90;
  let north = -90;
  for (const [lon, lat] of ring) {
    if (lon < west) west = lon;
    if (lon > east) east = lon;
    if (lat < south) south = lat;
    if (lat > north) north = lat;
  }
  return { west, east, south, north };
}

/**
 * Validate the shipped outline and add what the renderer needs (per-country
 * bounds). Returns `null` for anything that is not a real outline, so a broken
 * file becomes an honest “not available” state instead of an empty map.
 */
export function normaliseOutline(raw) {
  const countries = Array.isArray(raw?.countries) ? raw.countries : null;
  if (!countries || countries.length === 0) return null;
  const prepared = [];
  for (const country of countries) {
    const rings = Array.isArray(country?.rings) ? country.rings : [];
    const usable = [];
    for (const ring of rings) {
      if (!Array.isArray(ring) || ring.length < MIN_RING_POINTS) continue;
      const points = [];
      for (const point of ring) {
        if (!Array.isArray(point) || point.length !== 2) continue;
        const [lon, lat] = point;
        if (!Number.isFinite(lon) || !Number.isFinite(lat)) continue;
        points.push([lon, lat]);
      }
      if (points.length < MIN_RING_POINTS) continue;
      usable.push({ points, bounds: ringBounds(points) });
    }
    if (usable.length === 0) continue;
    prepared.push({
      name: String(country.name ?? ''),
      nameDe: country.nameDe ? String(country.nameDe) : null,
      iso: country.iso ? String(country.iso) : null,
      rings: usable,
    });
  }
  if (prepared.length === 0) return null;
  return { meta: raw.meta ?? {}, countries: prepared };
}

/**
 * The longitude/latitude window the viewport shows. `west`/`east` may fall
 * outside ±180° when the map is panned across the date line — that is exactly
 * what the intersection test needs.
 */
export function viewWindow(view) {
  const { z, originX, originY, width, height } = view;
  return {
    west: unprojectLon(originX, z),
    east: unprojectLon(originX + width, z),
    south: unprojectLat(originY + height, z),
    north: unprojectLat(originY, z),
  };
}

/** Do two degree boxes overlap? Both are “west ≤ east”, “south ≤ north”. */
export function boxesIntersect(a, b) {
  return a.west <= b.east && a.east >= b.west && a.south <= b.north && a.north >= b.south;
}

/**
 * A country is worth drawing when its box meets the viewport — also when the
 * viewport sits across the date line, where the same country appears 360° to
 * the east or west. The shifted copies are only used for the test, never for
 * the drawn geometry (a shifted copy of a ring is off-screen by construction).
 */
export function countryVisible(bounds, window) {
  if (boxesIntersect(bounds, window)) return true;
  const shiftedEast = { ...window, west: window.west - 360, east: window.east - 360 };
  const shiftedWest = { ...window, west: window.west + 360, east: window.east + 360 };
  return boxesIntersect(bounds, shiftedEast) || boxesIntersect(bounds, shiftedWest);
}

/** Clamp helper: keeps every drawn coordinate near the viewport. */
function clamp(value, min, max) {
  return value < min ? min : value > max ? max : value;
}

/**
 * Project the outline into viewport coordinates.
 *
 * Returns `{ land, borders, countries, points, window }`:
 *  - `land`: one array of `[x, y]` paths per drawn country ring (screen pixels,
 *    `drawWorld` fills them),
 *  - `borders`: the same rings, drawn as strokes on top,
 *  - `countries`: how many countries are visible (for the status line),
 *  - `points`: how many vertices were written (the harness reads it).
 *
 * Coordinates outside the viewport are clamped to a small margin instead of
 * being dropped: a polygon whose far corner lies off-screen still closes
 * correctly, because the clamped edge runs outside the canvas where nobody sees
 * it. That is what makes this cheap — no polygon clipping library.
 */
export function planWorldPaths(outline, view) {
  const window = viewWindow(view);
  const minX = -view.width * CLAMP_MARGIN;
  const maxX = view.width * (1 + CLAMP_MARGIN);
  const minY = -view.height * CLAMP_MARGIN;
  const maxY = view.height * (1 + CLAMP_MARGIN);
  const land = [];
  const borders = [];
  let countries = 0;
  let points = 0;
  for (const country of outline.countries) {
    let drawn = false;
    for (const ring of country.rings) {
      if (!countryVisible(ring.bounds, window)) continue;
      const path = [];
      for (const [lon, lat] of ring.points) {
        path.push([
          clamp(projectLon(lon, view.z) - view.originX, minX, maxX),
          clamp(projectLat(lat, view.z) - view.originY, minY, maxY),
        ]);
      }
      land.push(path);
      borders.push(path);
      points += path.length;
      drawn = true;
    }
    if (drawn) countries += 1;
  }
  return { land, borders, countries, points, window };
}

/**
 * 256 px-tile colours for the vector layer, read from the cantonal tokens when
 * the document provides them and from the documented values otherwise (the
 * fallbacks are the token values from `public/styles/zh-tokens.css`).
 */
export function worldTheme(root = typeof document === 'undefined' ? null : document.documentElement) {
  const read = (name, fallback) => {
    if (!root || typeof getComputedStyle !== 'function') return fallback;
    const value = getComputedStyle(root).getPropertyValue(name).trim();
    return value || fallback;
  };
  return {
    sea: read('--zh-blue-soft', '#edf5fa'),
    land: read('--zh-white', '#fff'),
    border: read('--zh-black-40', '#949494'),
    accent: read('--zh-blue', '#0070b4'),
    label: read('--zh-black-60', '#666'),
  };
}

/** Paint a plan onto a canvas of the given CSS size (device pixels handled). */
export function paintPlan(canvas, plan, view, theme, dpr = 1) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return plan;
  const pixelWidth = Math.max(1, Math.round(view.width * dpr));
  const pixelHeight = Math.max(1, Math.round(view.height * dpr));
  if (canvas.width !== pixelWidth) canvas.width = pixelWidth;
  if (canvas.height !== pixelHeight) canvas.height = pixelHeight;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, view.width, view.height);
  ctx.fillStyle = theme.sea;
  ctx.fillRect(0, 0, view.width, view.height);
  ctx.beginPath();
  for (const path of plan.land) {
    path.forEach(([x, y], index) => (index === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y)));
    ctx.closePath();
  }
  ctx.fillStyle = theme.land;
  ctx.fill('nonzero');
  // Borders: one path for all rings keeps the stroke joins consistent and makes
  // the whole layer a single draw call.
  ctx.beginPath();
  for (const path of plan.borders) {
    path.forEach(([x, y], index) => (index === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y)));
    ctx.closePath();
  }
  ctx.lineWidth = 0.8;
  ctx.strokeStyle = theme.border;
  ctx.stroke();
  return plan;
}

/** The documented swisstopo coverage, drawn as a dashed window on the outline. */
export function paintCoverage(canvas, view, switzerland, theme, dpr = 1) {
  const ctx = canvas.getContext('2d');
  if (!ctx || !switzerland) return;
  const x1 = projectLon(switzerland.west, view.z) - view.originX;
  const x2 = projectLon(switzerland.east, view.z) - view.originX;
  const y1 = projectLat(switzerland.north, view.z) - view.originY;
  const y2 = projectLat(switzerland.south, view.z) - view.originY;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.save();
  ctx.setLineDash([6, 4]);
  ctx.lineWidth = 2;
  ctx.strokeStyle = theme.accent;
  ctx.strokeRect(Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));
  ctx.restore();
}

let outlinePromise = null;
let outlineCache = null;

/**
 * Load (and cache) the shipped outline. A failure resets the cache, so a
 * “Erneut versuchen” button can really retry; the thrown error carries the real
 * reason (HTTP status, parse error) for the console and the status line.
 */
export async function loadOutline({ url = WORLD_OUTLINE_URL, fetchImpl = typeof fetch === 'function' ? fetch : null } = {}) {
  if (outlineCache) return outlineCache;
  if (outlinePromise) return outlinePromise;
  outlinePromise = (async () => {
    if (!fetchImpl) throw new Error('kein fetch verfügbar');
    const res = await fetchImpl(url, { headers: { accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const raw = await res.json();
    const outline = normaliseOutline(raw);
    if (!outline) throw new Error('unerwartetes Format');
    outlineCache = outline;
    return outline;
  })();
  try {
    return await outlinePromise;
  } catch (error) {
    outlinePromise = null;
    throw error;
  }
}

/** Drop the cache (tests, and the retry button after a failure). */
export function resetOutlineCache() {
  outlineCache = null;
  outlinePromise = null;
}

