/**
 * The “Welt (Umriss)” base map: project the shipped outline, paint it, and be
 * honest about the three real states (loading, ready, failed). The outline is
 * fetched on first use only, so a visitor who never leaves Switzerland never
 * pays for it.
 */
function renderWorld(originX, originY, w, h, z) {
  worldLayer.hidden = false;
  const view = { z, originX, originY, width: w, height: h };
  const theme = worldTheme(container);
  const dpr = typeof devicePixelRatio === 'number' && devicePixelRatio > 0 ? Math.min(devicePixelRatio, 3) : 1;
  if (worldOutline) {
    const plan = paintPlan(worldLayer, planWorldPaths(worldOutline, view), view, theme, dpr);
    paintCoverage(worldLayer, view, SWITZERLAND, theme, dpr);
    worldState = 'ready';
    setWorldStatus(
      `Welt-Übersicht: ${plan.countries} Länder mit belegtem Umriss in diesem Ausschnitt. ` +
        'Die gestrichelte Marke zeigt, wo swisstopo-Kacheln zur Verfügung stehen.',
    );
    return;
  }
  // Not loaded yet: sea colour as a placeholder, then one honest status line.
  paintPlan(worldLayer, { land: [], borders: [] }, view, theme, dpr);
  if (worldState === 'loading' || worldState === 'error') return;
  worldState = 'loading';
  setWorldStatus('Welt-Übersicht (Natural Earth) wird geladen …');
  void loadOutline()
    .then((outline) => {
      worldOutline = outline;
      worldState = 'ready';
      if (activeBase.kind === 'vector') render();
    })
    .catch((error) => {
      worldState = 'error';
      console.warn(`[map] Welt-Übersicht konnte nicht geladen werden: ${error?.message ?? error}`);
      setWorldStatus(`Die Welt-Übersicht konnte nicht geladen werden (${error?.message ?? error}). Die anderen Grundkarten sind nicht betroffen.`, {
        retry: true,
      });
    });
}

/** One status line under the map; the retry button is a real control. */
function setWorldStatus(text, { retry = false } = {}) {
  const status = qs('#map-world-status');
  const action = qs('#map-world-retry');
  if (status) {
    status.textContent = text;
    status.hidden = !text;
  }
  if (action) {
    action.replaceChildren(
      retry
        ? el('button', {
            class: 'zh-button zh-button--small zh-button--ghost',
            type: 'button',
            onclick: () => {
              worldState = '';
              render();
            },
            text: 'Welt-Übersicht erneut laden',
          })
        : '',
    );
    action.hidden = !retry;
  }
}

