arguments.content:
/**
 * “Welt (Umriss)” base map (maps-1).
 *
 * The map's raster base layers come from swisstopo and only cover Switzerland
 * (a tile over the North Sea is an all-white JPEG, verified 2026-10-19), so the
 * seed's 60+ world, Europe and overseas records sat on a blank surface. The
 * fourth base map is drawn from an outline that ships with the site:
 * `/data/world.geo.json`, built by `scripts/build-world.mjs` from Natural Earth
 * 1:110m Admin-0 countries (public domain).
 *
 * What is asserted here:
 *  - the shipped outline is the documented dataset (provenance, count, ranges),
 *    so a hand-edited or truncated file cannot become invented geography;
 *  - the projection in `world.js` agrees with the map's own projection in
 *    `map.js` (two implementations of Web Mercator must not drift apart);
 *  - the draw plan is pure and testable: visible countries produce paths,
 *    off-screen ones do not, coordinates stay near the viewport;
 *  - the loader reports failure instead of an empty map, and a retry works.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';

import {
  WORLD_OUTLINE_URL,
  loadOutline,
  normaliseOutline,
  paintPlan,
  planWorldPaths,
  projectLat,
  projectLon,
  resetOutlineCache,
  ringBounds,
  unprojectLat,
  unprojectLon,
  viewWindow,
  worldTheme,
} from '../public/app/world.js';
import { SWITZERLAND, TILE as MAP_TILE, latToTileY, lonToTileX } from '../public/app/map.js';
import { buildOutline, checkOutline, ringArea } from '../scripts/build-world.mjs';

const outlinePath = new URL('../public/data/world.geo.json', import.meta.url);
const shipped = async () => JSON.parse(await readFile(outlinePath, 'utf8'));

/** Zürich at zoom 8 as a real viewport: originX/originY are world pixels. */
const zurichView = (z = 8, width = 800, height = 500) => ({
  z,
  originX: lonToTileX(SWITZERLAND.west + 2, z) * MAP_TILE - width / 2,
  originY: latToTileY(47.4, z) * MAP_TILE - height / 2,
  width,
  height,
});

test('the shipped outline names its source, its licence and its date', async () => {
  const raw = await shipped();
  assert.equal(checkOutline(raw).length, 0, checkOutline(raw).join('; '));
  assert.match(raw.meta.source, /natural[- ]?earth/i);
  assert.match(raw.meta.license, /public domain/i);
  assert.match(raw.meta.retrieved, /^\d{4}-\d{2}-\d{2}$/);
  assert.equal(raw.meta.generator, 'scripts/build-world.mjs');
  assert.equal(raw.meta.dataset, 'ne_110m_admin_0_countries');
  assert.ok(raw.countries.length >= 150, `only ${raw.countries.length} countries`);
});

test('the outline is world-wide and includes the canton’s neighbours', async () => {
  const raw = await shipped();
  const names = new Set(raw.countries.map((country) => country.name));
  for (const name of ['Switzerland', 'Germany', 'France', 'Italy', 'Austria', 'Japan', 'Brazil', 'Australia']) {
    assert.ok(names.has(name), `missing ${name}`);
  }
  // The coordinate window is the real world, not a fragment of it.
  assert.ok(raw.bbox.west <= -179 && raw.bbox.east >= 179, JSON.stringify(raw.bbox));
  assert.ok(raw.bbox.south <= -85 && raw.bbox.north >= 83, JSON.stringify(raw.bbox));
  const switzerland = raw.countries.find((country) => country.name === 'Switzerland');
  const bounds = switzerland.rings.map(ringBounds).reduce((a, b) => ({
    west: Math.min(a.west, b.west),
    east: Math.max(a.east, b.east),
    south: Math.min(a.south, b.south),
    north: Math.max(a.north, b.north),
  }));
  // The data's own Swiss box has to contain the documented swisstopo coverage.
  assert.ok(bounds.west <= SWITZERLAND.west && bounds.east >= SWITZERLAND.east, JSON.stringify(bounds));
  assert.ok(bounds.south <= SWITZERLAND.south && bounds.north >= SWITZERLAND.north, JSON.stringify(bounds));
});

test('every coordinate of the shipped outline is a real degree value', async () => {
  const raw = await shipped();
  let points = 0;
  for (const country of raw.countries) {
    for (const ring of country.rings) {
      assert.ok(ring.length >= 4, `${country.name}: ${ring.length} points`);
      for (const point of ring) {
        const [lon, lat] = point;
        assert.ok(Number.isFinite(lon) && lon >= -180 && lon <= 180, `${country.name}: lon ${lon}`);
        assert.ok(Number.isFinite(lat) && lat >= -90 && lat <= 90, `${country.name}: lat ${lat}`);
        points += 1;
      }
    }
  }
  assert.equal(points, raw.meta.points, 'meta.points counts the real vertices');
  // Three decimals: ~110 m, far below one pixel of a world overview.
  const switzerland = raw.countries.find((country) => country.name === 'Switzerland');
  for (const [lon] of switzerland.rings.flat()) {
    assert.equal(Math.round(lon * 1000) / 1000, lon, `rounded: ${lon}`);
  }
});

test('world.js projects exactly like the map’s own projection', () => {
  for (const z of [0, 3, 8, 12, 18]) {
    for (const [lon, lat] of [
      [8.5417, 47.3769],
      [-180, -85.05112878],
      [179.9999, 85.05112878],
      [-58.4, -34.6],
      [139.7, 35.7],
    ]) {
      assert.equal(projectLon(lon, z), lonToTileX(lon, z) * MAP_TILE, `lon ${lon} at z${z}`);
      assert.equal(projectLat(lat, z), latToTileY(lat, z) * MAP_TILE, `lat ${lat} at z${z}`);
    }
  }
  // The inverse is the inverse (and the clamp keeps poles inside Mercator).
  assert.ok(Math.abs(unprojectLon(projectLon(8.5417, 7), 7) - 8.5417) < 1e-9);
  assert.ok(Math.abs(unprojectLat(projectLat(47.3769, 7), 7) - 47.3769) < 1e-9);
  assert.ok(Number.isFinite(projectLat(-90, 4)) && Number.isFinite(projectLat(90, 4)));
});

test('the viewport window is the longitude/latitude box the visitor sees', () => {
  const view = zurichView(8, 800, 500);
  const window = viewWindow(view);
  assert.ok(window.west < 8 && window.east > 8, JSON.stringify(window));
  assert.ok(window.south < 47.4 && window.north > 47.4, JSON.stringify(window));
  // Across the date line the window is allowed to leave ±180°.
  const pacific = viewWindow({
    z: 3,
    originX: (2 ** 3 * MAP_TILE * 179) / 360,
    originY: 0,
    width: 800,
    height: 500,
  });
  assert.ok(pacific.east > 180 || pacific.west < -180, JSON.stringify(pacific));
});

test('only countries that intersect the viewport are drawn', async () => {
  const outline = normaliseOutline(await shipped());
  const plan = planWorldPaths(outline, zurichView(8, 800, 500));
  assert.ok(plan.countries >= 3, `expected several neighbours, got ${plan.countries}`);
  // A country window of ~5° around Zürich cannot contain Japan or Brazil.
  const drawn = new Set();
  for (let i = 0; i < outline.countries.length; i += 1) drawn.add(i);
  const bigPlan = planWorldPaths(outline, { z: 0, originX: 0, originY: 0, width: 1024, height: 1024 });
  assert.ok(bigPlan.countries > 100, `whole world should draw most countries, got ${bigPlan.countries}`);
  assert.equal(bigPlan.land.length, bigPlan.borders.length);
  assert.ok(bigPlan.points > plan.points, 'the whole world has more vertices than one region');
});

test('drawn coordinates stay near the viewport (no runaway geometry)', async () => {
  const outline = normaliseOutline(await shipped());
  const view = zurichView(12, 640, 400);
  const plan = planWorldPaths(outline, view);
  assert.ok(plan.land.length > 0);
  let far = 0;
  for (const path of plan.land) {
    for (const [x, y] of path) {
      if (!Number.isFinite(x) || !Number.isFinite(y)) far += 1;
      else if (x < -view.width * 2 - 1 || x > view.width * 3 + 1 || y < -view.height * 2 - 1 || y > view.height * 3 + 1) far += 1;
    }
  }
  assert.equal(far, 0, `${far} coordinates escaped the clamp`);
  // Deep zoom inside Switzerland keeps the shape (the canton is land).
  const deep = planWorldPaths(outline, zurichView(16, 640, 400));
  assert.ok(deep.land.length > 0, 'Switzerland must still be drawn at zoom 16');
});

test('a broken outline never becomes an empty map', () => {
  assert.equal(normaliseOutline(null), null);
  assert.equal(normaliseOutline({}), null);
  assert.equal(normaliseOutline({ countries: [] }), null);
  assert.equal(normaliseOutline({ countries: [{ name: 'Nowhere', rings: [] }] }), null);
  assert.equal(normaliseOutline({ countries: [{ name: 'Nowhere', rings: [[[0, 0]]] }] }), null);
  const partial = normaliseOutline({
    countries: [
      { name: 'Broken', rings: [[[0, 0], [1, 1], [null, 2], ['x', 3], [4, 4], [5, 5]]] },
      { name: 'Whole', rings: [[[0, 0], [1, 1], [2, 2], [3, 3], [4, 4]]] },
    ],
  });
  assert.equal(partial.countries.length, 1);
  assert.equal(partial.countries[0].name, 'Whole');
  assert.equal(partial.countries[0].rings[0].points.length, 5);
});

test('the painter fills land first and strokes the borders afterwards', async () => {
  const outline = normaliseOutline(await shipped());
  const calls = [];
  const ctx = {
    setTransform: (...args) => calls.push(['setTransform', ...args]),
    clearRect: (...args) => calls.push(['clearRect', ...args]),
    fillRect: (...args) => calls.push(['fillRect', ...args]),
    beginPath: () => calls.push(['beginPath']),
    moveTo: () => calls.push(['moveTo']),
    lineTo: () => calls.push(['lineTo']),
    closePath: () => calls.push(['closePath']),
    fill: (rule) => calls.push(['fill', rule]),
    stroke: () => calls.push(['stroke']),
    save: () => calls.push(['save']),
    restore: () => calls.push(['restore']),
    setLineDash: () => calls.push(['setLineDash']),
    strokeRect: () => calls.push(['strokeRect']),
  };
  const canvas = { width: 0, height: 0, getContext: () => ctx };
  const view = zurichView(9, 400, 300);
  const plan = paintPlan(canvas, planWorldPaths(outline, view), view, worldTheme(null), 2);
  assert.equal(canvas.width, 800, 'device pixels');
  assert.equal(canvas.height, 600);
  assert.ok(plan.countries >= 1);
  const names = calls.map((call) => call[0]);
  assert.equal(names.filter((name) => name === 'fill').length, 1);
  assert.equal(names.filter((name) => name === 'stroke').length, 1);
  assert.ok(names.indexOf('fill') < names.indexOf('stroke'), 'borders are drawn over the land');
  assert.ok(names.includes('fillRect'), 'the sea is painted');
});

test('the theme reads the cantonal tokens and falls back to their values', () => {
  const documentElement = { getPropertyValue: (name) => (name === '--zh-blue-soft' ? ' #edf5fa ' : '') };
  const fromTokens = worldTheme(documentElement);
  assert.equal(fromTokens.sea, '#edf5fa');
  assert.equal(fromTokens.land, '#fff', 'documented fallback for --zh-white');
  assert.equal(fromTokens.border, '#949494');
  const offline = worldTheme(null);
  assert.equal(offline.sea, '#edf5fa');
  assert.equal(offline.accent, '#0070b4');
});

test('the loader caches a good outline, reports failures and allows a retry', async () => {
  resetOutlineCache();
  const raw = await shipped();
  let calls = 0;
  const okFetch = async () => {
    calls += 1;
    return { ok: true, json: async () => raw };
  };
  const first = await loadOutline({ fetchImpl: okFetch });
  const second = await loadOutline({ fetchImpl: okFetch });
  assert.equal(calls, 1, 'the second call is served from the cache');
  assert.equal(first, second);
  assert.ok(first.countries.length >= 150);

  resetOutlineCache();
  await assert.rejects(() => loadOutline({ fetchImpl: async () => ({ ok: false, status: 404 }) }), /HTTP 404/);
  // A failed load must not be cached: the retry button has to reach the server.
  const retry = await loadOutline({ fetchImpl: okFetch });
  assert.ok(retry.countries.length >= 150, 'a retry after a failure works');
  resetOutlineCache();
  await assert.rejects(() => loadOutline({ fetchImpl: async () => ({ ok: true, json: async () => ({ nope: true }) }) }), /Format/);
  resetOutlineCache();
  await assert.rejects(() => loadOutline({ fetchImpl: null }), /fetch/);
  assert.equal(WORLD_OUTLINE_URL, '/data/world.geo.json');
});

test('the build script drops specks, keeps rings closed and rounds coordinates', () => {
  const geojson = {
    features: [
      {
        properties: { NAME: 'Specks', ISO_A3: '-99' },
        geometry: {
          type: 'MultiPolygon',
          coordinates: [
            [[[0, 0], [0.0001, 0], [0.0001, 0.0001], [0, 0.0001], [0, 0]]], // ~0.000001 deg² → dropped
            [[[1, 1], [1.5, 1], [1.5, 1.5], [1, 1.5], [1, 1], [1, 1]]], // duplicate closing point
          ],
        },
      },
      {
        properties: { NAME: 'Hole land', NAME_DE: 'Lochland', ISO_A3: 'HLL' },
        geometry: { type: 'Polygon', coordinates: [[[2, 2], [2, 3], [3, 3], [3, 2], [2, 2]], [[2.4, 2.4], [2.6, 2.4], [2.6, 2.6]]] },
      },
      { properties: {}, geometry: { type: 'Polygon', coordinates: [[[4, 4], [4, 5], [5, 5], [5, 4], [4, 4]]] } },
    ],
  };
  const built = buildOutline(geojson, { retrieved: '2026-10-19' });
  assert.equal(built.countries.length, 2, 'the nameless feature and the speck are dropped');
  assert.equal(built.countries[0].name, 'Hole land');
  assert.equal(built.countries[0].nameDe, 'Lochland');
  assert.equal(built.countries[1].iso, null, '-99 is not an ISO code');
  assert.equal(built.countries[1].rings[0].length, 4, 'the closing point is not stored twice');
  assert.equal(built.meta.retrieved, '2026-10-19');
  assert.ok(built.meta.points >= 8);
  // The specks rule is “too small to be land”, not “few points”.
  assert.ok(ringArea([[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]]) > 0.5);
});

