import { launch } from '/tmp/probe/cdp.mjs';

const BASE = process.env.BASE || 'http://127.0.0.1:8787';
const cdp = await launch({ width: 1280, height: 900, port: 9355 });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const failures = [];
const ok = (name, cond, detail = '') => {
  console.log(`${cond ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`);
  if (!cond) failures.push(name);
};

await cdp.goto(`${BASE}/?base=welt&lat=20&lon=10&z=3`);
await sleep(4000);

const state = await cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  const chips = [...document.querySelectorAll('#base-layer-switch [data-base-key]')].map((c) => ({ key: c.dataset.baseKey, pressed: c.getAttribute('aria-pressed'), label: c.getAttribute('aria-label') }));
  const status = document.querySelector('#map-world-status');
  const badge = document.querySelector('.map-badge')?.textContent ?? '';
  let ink = null;
  if (canvas) {
    const g = canvas.getContext('2d');
    const d = g.getImageData(0, 0, canvas.width, canvas.height).data;
    const hist = new Map();
    for (let i = 0; i < d.length; i += 4 * 13) {
      const k = d[i] + ',' + d[i+1] + ',' + d[i+2];
      hist.set(k, (hist.get(k) || 0) + 1);
    }
    ink = { size: [canvas.width, canvas.height], cssSize: [canvas.clientWidth, canvas.clientHeight], top: [...hist.entries()].sort((a,b)=>b[1]-a[1]).slice(0,3), distinct: hist.size };
  }
  return {
    canvas: ink,
    hidden: canvas?.hidden ?? null,
    chips, status: status ? { text: status.textContent, hidden: status.hidden } : null, badge,
    url: location.search,
    tiles: document.querySelectorAll('.map-layer--base img').length,
    markers: document.querySelectorAll('.map-marker').length,
  };
})()`);
console.log(JSON.stringify(state, null, 1));
ok('the canvas is drawn (not a single flat colour)', state.canvas && state.canvas.distinct > 3, JSON.stringify(state.canvas?.top));
ok('the world chip is pressed', state.chips?.some((c) => c.key === 'welt' && c.pressed === 'true'));
ok('no raster tiles are requested outside Switzerland', state.tiles === 0, `tiles=${state.tiles}`);
ok('the status line states what is shown', /Länder/.test(state.status?.text ?? ''), state.status?.text);

// Pan to Japan (a record's own region) and check the outline follows.
const japan = await cdp.eval(`(async () => {
  const store = window.__kz?.store;
  return true;
})()`);

// Simulate a pan by dragging.
await cdp.eval(`(() => { const el = document.querySelector('#map'); const r = el.getBoundingClientRect(); window.__center = [r.left + r.width/2, r.top + r.height/2]; return true; })()`);
const center = await cdp.eval('window.__center');
await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: center[0], y: center[1], button: 'left', clickCount: 1 });
await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: center[0] - 600, y: center[1], button: 'left' });
await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: center[0] - 600, y: center[1], button: 'left', clickCount: 1 });
await sleep(1200);
const after = await cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  const g = canvas.getContext('2d');
  const d = g.getImageData(0, 0, canvas.width, canvas.height).data;
  const hist = new Map();
  for (let i = 0; i < d.length; i += 4 * 13) { const k = d[i]+','+d[i+1]+','+d[i+2]; hist.set(k, (hist.get(k)||0)+1); }
  return { url: location.search, distinct: hist.size, top: [...hist.entries()].sort((a,b)=>b[1]-a[1]).slice(0,2), status: document.querySelector('#map-world-status')?.textContent };
})()`);
console.log(JSON.stringify(after, null, 1));
ok('the outline follows a pan (still several colours)', after.distinct > 2, String(after.distinct));

await cdp.shot('/tmp/shots-764-world/welt.png');
await cdp.setViewport(390, 844);
await sleep(1200);
await cdp.shot('/tmp/shots-764-world/welt-mobile.png');

// Switch back to the raster base and make sure the canvas is cleared.
await cdp.eval(`document.querySelector('#base-layer-switch [data-base-key="grau"]').click()`);
await sleep(2500);
const back = await cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  const g = canvas.getContext('2d');
  const d = g.getImageData(0, 0, canvas.width, canvas.height).data;
  let nonEmpty = 0;
  for (let i = 3; i < d.length; i += 4 * 7) if (d[i] !== 0) nonEmpty += 1;
  return { hidden: canvas.hidden, nonEmpty, tiles: document.querySelectorAll('.map-layer--base img').length, badge: document.querySelector('.map-badge')?.textContent };
})()`);
console.log(JSON.stringify(back));
ok('switching back hides and clears the outline', back.hidden === true && back.nonEmpty === 0, JSON.stringify(back));
ok('the raster tiles come back', back.tiles > 0, `tiles=${back.tiles}`);

console.log(failures.length === 0 ? '\nALL WORLD-LAYER CHECKS PASSED' : `\n${failures.length} FAILED: ${failures.join(', ')}`);
await cdp.close();
process.exit(failures.length === 0 ? 0 : 1);

