import { launch } from '/tmp/probe/cdp.mjs';

const BASE = process.env.BASE || 'http://127.0.0.1:8787';
const cdp = await launch({ width: 1280, height: 900, port: 9356 });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let failures = 0;
const ok = (name, cond, detail = '') => {
  console.log(`${cond ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`);
  if (!cond) failures += 1;
};

const sample = async () => cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  if (!canvas) return null;
  const g = canvas.getContext('2d');
  const d = g.getImageData(0, 0, canvas.width, canvas.height).data;
  const hist = new Map();
  for (let i = 0; i < d.length; i += 4 * 11) { const k = d[i]+','+d[i+1]+','+d[i+2]; hist.set(k, (hist.get(k)||0)+1); }
  const top = [...hist.entries()].sort((a,b)=>b[1]-a[1]);
  return { url: location.search, distinct: hist.size, top: top.slice(0,3), hidden: canvas.hidden, size: [canvas.width, canvas.height], status: document.querySelector('#map-world-status')?.textContent ?? '' };
})()`);

for (const [label, query, expectInk] of [
  ['Tokyo', '?base=welt&lat=35.7&lon=139.7&z=9', true],
  ['date line (Bering)', '?base=welt&lat=64&lon=-179&z=4', true],
  ['deep zoom inside Switzerland', '?base=welt&lat=47.3769&lon=8.5417&z=16', true],
  ['zoomed far into the ocean', '?base=welt&lat=0&lon=-30&z=14', false],
]) {
  await cdp.goto(`${BASE}/${query}`);
  await sleep(3500);
  const s = await sample();
  const land = s.top.find(([colour]) => colour === '255,255,255')?.[1] ?? 0;
  console.log(`${label}:`, JSON.stringify({ distinct: s.distinct, sea: s.top[0], land, status: s.status.slice(0, 40) }));
  if (expectInk) ok(`${label}: land or borders are drawn`, s.distinct > 2, `distinct=${s.distinct}`);
  else ok(`${label}: open sea is a flat surface`, s.distinct <= 2, `distinct=${s.distinct}`);
}

// Pan with a real mouse drag (the same synthetic events the harness uses).
await cdp.goto(`${BASE}/?base=welt&lat=47&lon=8&z=5`);
await sleep(3500);
const before = await sample();
const box = await cdp.eval(`(() => { const r = document.querySelector('#map').getBoundingClientRect(); return { x: Math.round(r.left + r.width/2), y: Math.round(r.top + r.height/2) }; })()`);
const point = { x: box.x, y: box.y, button: 'left', clickCount: 1, buttons: 1 };
await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...point });
await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...point });
for (let dx = 40; dx <= 360; dx += 40) {
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: box.x - dx, y: box.y, button: 'left', buttons: 1 });
  await sleep(40);
}
const release = { x: box.x - 360, y: box.y, button: 'left', clickCount: 1, buttons: 0 };
await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...release });
await sleep(1500);
const after = await sample();
console.log('pan before/after:', before.url, '->', after.url, `distinct ${before.distinct} -> ${after.distinct}`);
ok('a mouse drag pans the world map', before.url !== after.url, `${before.url} -> ${after.url}`);
ok('the outline is redrawn after the pan', after.distinct > 2 && !after.hidden, `distinct=${after.distinct} hidden=${after.hidden}`);

// Keyboard: zoom with + and check the outline follows without tiles.
await cdp.goto(`${BASE}/?base=welt&lat=47&lon=8&z=5`);
await sleep(3000);
await cdp.eval(`document.querySelector('#map').focus(); true`);
const zoomBefore = await cdp.eval(`location.search`);
await cdp.key('+', 'Equal', 187, { modifiers: 0 });
await sleep(1200);
const zoomAfter = await sample();
ok('keyboard zoom works on the world base map', zoomBefore !== zoomAfter.url || zoomAfter.distinct > 2, `${zoomBefore} -> ${zoomAfter.url}`);

// The URL key is validated: an unknown base falls back to the default raster.
await cdp.goto(`${BASE}/?base=weltX`);
await sleep(2500);
const fallback = await cdp.eval(`({ pressed: [...document.querySelectorAll('#base-layer-switch [data-base-key]')].filter((c) => c.getAttribute('aria-pressed') === 'true').map((c) => c.dataset.baseKey), canvasHidden: document.querySelector('.map-layer--world')?.hidden, tiles: document.querySelectorAll('.map-layer--base img').length })`);
ok('an unknown base key falls back to the documented default', fallback.pressed.join() === 'farbe' && fallback.canvasHidden === true && fallback.tiles > 0, JSON.stringify(fallback));

console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} FAILED`);
await cdp.close();
process.exit(failures === 0 ? 0 : 1);

