  const mod = await import('/app/world.js');
  const raw = await (await fetch('/data/world.geo.json')).json();
  const outline = mod.normaliseOutline(raw);
  const map = document.querySelector('#map');
  const r = map.getBoundingClientRect();
  const width = Math.round(r.width), height = Math.round(r.height);
  const params = new URLSearchParams(location.search);
  const z = Number(params.get('z')), lon = Number(params.get('lon')), lat = Number(params.get('lat'));
  const originX = mod.projectLon(lon, z) - width / 2, originY = mod.projectLat(lat, z) - height / 2;
  const view = { z, originX, originY, width, height };
  const win = mod.viewWindow(view);
  const plan = mod.planWorldPaths(outline, view);
  return { search: location.search, z, lon, lat, width, height, win, countries: plan.countries, rings: plan.land.length, points: plan.points };
})()`);
console.log(JSON.stringify(out, null, 1));
