await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });

/* --- 8r. Grundkarte “Welt (Umriss)” (maps-1) -------------------------- */
// swisstopo answers a white tile (or 404) outside Switzerland, so the seed's
// 60+ world, Europe and overseas records sat on a blank surface. The fourth
// base map is drawn from the outline that ships with the site
// (/data/world.geo.json, Natural Earth, public domain). This section checks
// the real canvas, the honest status line, the attribution, that no raster
// tile is requested for it, and that switching back restores the tiles.
await cdp.send('Page.navigate', { url: `${BASE_URL}/?base=welt&lat=40&lon=-20&z=3` });
await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'Welt base page' });
let worldLoaded = true;
try {
  await cdp.waitFor(`/Länder/.test(document.querySelector('#map-world-status')?.textContent || '')`, { label: 'world outline', timeout: 20_000 });
} catch {
  worldLoaded = false;
}
const worldBase = await cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  const status = document.querySelector('#map-world-status');
  const chips = [...document.querySelectorAll('#base-layer-switch [data-base-key]')];
  const ink = { distinct: 0, sea: 0, land: 0, borders: 0 };
  if (canvas && !canvas.hidden) {
    const g = canvas.getContext('2d');
    const d = g.getImageData(0, 0, canvas.width, canvas.height).data;
    const seen = new Set();
    for (let i = 0; i < d.length; i += 4 * 17) {
      const key = d[i] + ',' + d[i + 1] + ',' + d[i + 2];
      seen.add(key);
      if (key === '237,245,250') ink.sea += 1;
      else if (key === '255,255,255') ink.land += 1;
    }
    ink.distinct = seen.size;
    ink.size = [canvas.width, canvas.height];
  }
  return {
    url: location.search,
    canvas: Boolean(canvas),
    hidden: canvas?.hidden ?? null,
    ink,
    status: status ? { text: status.textContent, hidden: status.hidden } : null,
    retryHidden: document.querySelector('#map-world-retry')?.hidden ?? null,
    chips: chips.map((c) => c.dataset.baseKey),
    pressed: chips.filter((c) => c.getAttribute('aria-pressed') === 'true').map((c) => c.dataset.baseKey),
    tiles: document.querySelectorAll('.map-layer--base img').length,
    badge: document.querySelector('.map-badge')?.textContent || '',
    markers: document.querySelectorAll('.map-marker').length,
    outlineRequests: ${JSON.stringify(apiRequests)}.filter((u) => u.includes('world.geo.json')).length,
  };
})()`);
check(
  'the fourth base map draws the real world outline instead of white tiles',
  worldLoaded &&
    worldBase.canvas &&
    worldBase.hidden === false &&
    worldBase.pressed.join(',') === 'welt' &&
    worldBase.chips.includes('welt') &&
    worldBase.ink.distinct > 3 &&
    worldBase.ink.land > 0 &&
    worldBase.ink.sea > 0 &&
    worldBase.tiles === 0 &&
    worldBase.markers > 0 &&
    worldBase.outlineRequests === 1,
  JSON.stringify({ loaded: worldLoaded, hidden: worldBase.hidden, chips: worldBase.chips, pressed: worldBase.pressed, ink: worldBase.ink, tiles: worldBase.tiles, markers: worldBase.markers, outlineRequests: worldBase.outlineRequests }),
);
check(
  'the world base map names its source and says what the dashed mark means',
  /Welt-Übersicht: \d+ Länder/.test(worldBase.status?.text || '') &&
    worldBase.status?.hidden === false &&
    /Natural Earth/.test(worldBase.badge) &&
    /gemeinfrei/.test(worldBase.badge) &&
    /swisstopo-Kacheln nur innerhalb der Schweiz/.test(worldBase.badge) &&
    worldBase.retryHidden === true &&
    worldBase.url.includes('base=welt'),
  JSON.stringify({ status: worldBase.status, badge: worldBase.badge, retryHidden: worldBase.retryHidden, url: worldBase.url }),
);
await cdp.shot('14-welt-umriss.png');

// Switching back: the tiles return, the canvas is hidden and cleared (a
// leftover outline would paint over the raster base map).
await cdp.click('#base-layer-switch [data-base-key="grau"]');
await cdp.waitFor(`document.querySelectorAll('.map-layer--base img').length > 0`, { label: 'tiles after the world base', timeout: 15_000 });
await sleep(500);
const worldBack = await cdp.eval(`(() => {
  const canvas = document.querySelector('.map-layer--world');
  let nonEmpty = 0;
  if (canvas) {
    const d = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data;
    for (let i = 3; i < d.length; i += 4 * 7) if (d[i] !== 0) nonEmpty += 1;
  }
  return {
    hidden: canvas?.hidden ?? null,
    nonEmpty,
    tiles: [...document.querySelectorAll('.map-layer--base img')].filter((i) => i.naturalWidth > 0).length,
    badge: document.querySelector('.map-badge')?.textContent || '',
    status: document.querySelector('#map-world-status')?.textContent || '',
    statusHidden: document.querySelector('#map-world-status')?.hidden ?? null,
  };
})()`);
check(
  'leaving the world base map restores the swisstopo tiles and clears the outline',
  worldBack.hidden === true &&
    worldBack.nonEmpty === 0 &&
    worldBack.tiles > 0 &&
    /© swisstopo/.test(worldBack.badge) &&
    worldBack.statusHidden === true,
  JSON.stringify(worldBack),
);

// (the series section runs after 8j and opens another record of the seed)

